def describe_global_intelligence_network() -> str:
    lines = [
        "TitanAI Global Intelligence Network Era",
        "",
        "This era expands TitanAI into a global-scale intelligence coordination framework spanning knowledge, software, engineering, agents, research, business, security, operations, and evolution.",
        "",
    ]
    for capability in GLOBAL_INTELLIGENCE_CAPABILITIES:
        lines.append(f"- {capability.version} {capability.name} [{capability.domain}]")
        lines.append(f"  {capability.purpose}")
    return "\n".join(lines)
